B.bJt=new A.JL(B.hu,"Haz\u0131r bir sunumun varsa PDF olarak ekle (iste\u011fe ba\u011fl\u0131); yoksa yukar\u0131daki Notlar yeterli.",null)
B.bJu=new A.hk("GitHub'daki her push, PR ve s\xfcr\xfcm bu ba\u011flant\u0131yla Hareketler'e ve proje sohbetine d\xfc\u015fer; issue kapan\u0131nca g\xf6rev biter. Kurulum ve onar\u0131m tek d\xfc\u011fme; ard\u0131ndan GitHub bir deneme olay\u0131 g\xf6nderir.",null)
B.bJv=new A.hk("Kodun durdu\u011fu yer GitHub. Hesab\u0131n yoksa \xfccretsiz a\xe7, sonra kullan\u0131c\u0131 ad\u0131n\u0131 buraya yaz; projeye atand\u0131\u011f\u0131nda repo eri\u015fimi bu hesaba verilir. Token gerekmez.",null)
B.bJw=new A.hk("Ekibin b\xfct\xfcn repolar\u0131 tek bir GitHub organizasyonunun alt\u0131nda durur; eri\u015fimi kimin g\xf6rece\u011fini Ekip Panel y\xf6netir. Organizasyonun yoksa GitHub'da \xfccretsiz a\xe7abilirsin.",null)
B.bJx=new A.hk("Token'\u0131 yaln\u0131zca admin girer.",null)
B.bJy=new A.hk('Her g\xf6rev GitHub\'da bir issue olur; commit mesaj\u0131na "#numara" yaz\u0131l\u0131p PR birle\u015fince g\xf6rev kendili\u011finden biter. Yeni g\xf6revlerde bu zaten kendili\u011finden olur; eskiler i\xe7in bir kez e\u015fitle.',null)
B.bJz=new A.hk("Token ge\xe7erli mi, organizasyon bulunuyor mu, token sahibi orada y\xf6netici mi diye bakar. Hepsi tamamsa projelerde repo a\xe7ma ve ekip eri\u015fimi kendili\u011finden \xe7al\u0131\u015f\u0131r.",null)
B.bJA=new A.hk("Hen\xfcz \xfcyesi oldu\u011fun bir proje yok.",null)
B.bJB=new A.hk("Y\xf6netici seni projeye atay\u0131p eri\u015fimi e\u015fitleyince GitHub e-posta ile davet g\xf6nderir. Kabul etmeden repoyu g\xf6remezsin; a\u015fa\u011f\u0131daki d\xfc\u011fme davet sayfas\u0131n\u0131 a\xe7ar.",null)
B.bJC=new A.hk("\u0130\u015fin bitince g\xf6nder (g\xf6rev numaras\u0131n\u0131 commit mesaj\u0131na yaz, PR birle\u015fince g\xf6rev biter):",null)
B.bJD=new A.hk('Bilgisayar\u0131nda Git kurulu olmal\u0131 (git-scm.com). Terminali a\xe7, a\u015fa\u011f\u0131daki komutlar\u0131 s\u0131rayla yap\u0131\u015ft\u0131r. Her i\u015fe ba\u015flamadan \xf6nce "git pull" ile g\xfcncel kodu al.',null)
B.bJE=new A.hk("Bunu yaln\u0131zca admin de\u011fi\u015ftirir.",null)
